        "code": "buildDialogShell( QDialog* dialog,\n\t\t\t\t\t\t\t\t\t\t const QString& windowTitle,\n\t\t\t\t\t\t\t\t\t\t int width,\n\t\t\t\t\t\t\t\t\t\t int height,\n\t\t\t\t\t\t\t\t\t\t HeaderIcon headerIcon,\n\t\t\t\t\t\t\t\t\t\t QWidget*& headerWidget,\n\t\t\t\t\t\t\t\t\t\t QWidget*& brandPanel,\n\t\t\t\t\t\t\t\t\t\t QWidget*& contentPanel,\n\t\t\t\t\t\t\t\t\t\t QVBoxLayout*& contentLayout,\n\t\t\t\t\t\t\t\t\t\t QWidget*& footerWidget,\n\t\t\t\t\t\t\t\t\t\t bool includeBrandPanel )\n{\n\tdialog->setWindowTitle( windowTitle );\n\tdialog->setWindowFlags( dialog->windowFlags() | Qt::WindowStaysOnTopHint );\n\tdialog->setModal( true );\n\tdialog->setFixedSize( width, height );\n\tdialog->setStyleSheet( dialogStyleSheet() );\n\tcenterDialogOnScreen( dialog, width, height );\n\n\tauto* rootLayout = new QVBoxLayout( dialog );\n\trootLayout->setContentsMargins( 0, 0, 0, 0 );\n\trootLayout->setSpacing( 0 );\n\n\theaderWidget = createHeader( dialog, windowTitle, headerIcon );\n\trootLayout->addWidget( headerWidget );\n\n\tauto* bodyWidget = new QWidget( dialog );\n\tbodyWidget->setStyleSheet( QStringLiteral( \"background: transparent;\" ) );\n\tauto* bodyLayout = new QHBoxLayout( bodyWidget );\n\tbodyLayout->setContentsMargins( 24, 24, 24, 16 );\n\tbodyLayout->setSpacing( 24 );\n\n\tbrandPanel = nullptr;\n\tif( includeBrandPanel )\n\t{\n\t\tbrandPanel = createBrandPanel( bodyWidget );\n\t\tbodyLayout->addWidget( brandPanel );\n\t\tbodyLayout->addWidget( createVerticalSeparator( bodyWidget ) );\n\t}\n\n\tcontentPanel = new QWidget( bodyWidget );\n\tcontentPanel->setObjectName( QStringLiteral( \"cimedContentPanel\" ) );\n\tcontentPanel->setStyleSheet( contentPanelStyleSheet() );\n\tcontentLayout = new QVBoxLayout( contentPanel );\n\tcontentLayout->setContentsMargins( 14, 14, 14, 14 );\n\tcontentLayout->setSpacing( 10 );\n\n\tbodyLayout->addWidget( contentPanel, 1 );\n\trootLayout->addWidget( bodyWidget, 1 );\n\n\tfooterWidget = createFooter( dialog );\n\trootLayout->addWidget( footerWidget );\n}",
