        "code": "checkProtectedFile( const QString& filePath, const QString& backup, const QString& fileLabel )\n\n{\n\n\tif( isWatcherSuppressed() )\n\n\t{\n\n\t\treturn;\n\n\t}\n\n\n\n\tif( QFile::exists( filePath ) == false )\n\n\t{\n\n\t\tif( backup.isEmpty() == false )\n\n\t\t{\n\n\t\t\treportUnauthorizedChange( filePath, fileLabel );\n\n\t\t}\n\n\t\treturn;\n\n\t}\n\n\n\n\tQString currentContent;\n\n\tif( AccessLogWriter::tryReadLogFileContent( filePath, currentContent ) == false )\n\n\t{\n\n\t\tvWarning() << \"[tamper-log-protection] skipping check due to read failure on\" << fileLabel;\n\n\t\treturn;\n\n\t}\n\n\n\n\tif( AccessLogWriter::logContentsEqual( currentContent, backup ) )\n\n\t{\n\n\t\treturn;\n\n\t}\n\n\n\n\tif( AccessLogWriter::isLegitimateProtectedLogAppend( backup, currentContent ) )\n\n\t{\n\n\t\tupdateBackupForPath( filePath );\n\n\t\treturn;\n\n\t}\n\n\n\n\tQString retryContent;\n\n\tQThread::msleep( 400 );\n\n\tif( AccessLogWriter::tryReadLogFileContent( filePath, retryContent ) &&\n\n\t\tAccessLogWriter::isLegitimateProtectedLogAppend( backup, retryContent ) )\n\n\t{\n\n\t\tupdateBackupForPath( filePath );\n\n\t\treturn;\n\n\t}\n\n\n\n\tif( isAccessLogPath( filePath ) && AccessLogWriter::accessLogFileHasValidIntegrity( filePath ) )\n\n\t{\n\n\t\tvDebug() << \"[tamper-log-protection] ignoring change on access log with valid hashes\";\n\n\t\tupdateBackupForPath( filePath );\n\n\t\treturn;\n\n\t}\n\n\n\n\treportUnauthorizedChange( filePath, fileLabel );\n\n}",
