        "file": "core/src/CimedVersionAlertPresenter.cpp",
        "code": "/*\n\n * CimedVersionAlertPresenter.cpp - routes version alert dialog to session worker\n\n */\n\n\n\n#include \"CimedVersionAlertPresenter.h\"\n\n\n\n#include \"BuiltinFeatures.h\"\n\n#include \"FeatureWorkerManager.h\"\n\n#include \"SystemTrayIcon.h\"\n\n#include \"VeyonCore.h\"\n\n\n\nCimedVersionAlertPresenter::CimedVersionAlertPresenter( QObject* parent ) :\n\n\tQObject( parent ),\n\n\tm_feature( Feature( QLatin1String( staticMetaObject.className() ),\n\n\t\t\t\t\t\tFeature::Flag::Service | Feature::Flag::Worker | Feature::Flag::Builtin,\n\n\t\t\t\t\t\tFeature::Uid( \"c8f4a2e1-5d6b-4a9c-8f2e-1b3d7c9e0a4f\" ),\n\n\t\t\t\t\t\tFeature::Uid(),\n\n\t\t\t\t\t\ttr( \"CIMED version alert\" ), {}, {} ) ),\n\n\tm_features( { m_feature } )\n\n{\n\n}\n\n\n\nvoid CimedVersionAlertPresenter::showAlert( FeatureWorkerManager& featureWorkerManager,\n\n\t\t\t\t\t\t\t\t\t\t\tconst QString& originIp,\n\n\t\t\t\t\t\t\t\t\t\t\tconst QString& originHost,\n\n\t\t\t\t\t\t\t\t\t\t\tconst QString& adUser,\n\n\t\t\t\t\t\t\t\t\t\t\tconst QString& adDisplayName,\n\n\t\t\t\t\t\t\t\t\t\t\tconst QString& detectedVersion )\n\n{\n\n\tVeyonCore::builtinFeatures().systemTrayIcon().showVersionAlert( featureWorkerManager,\n\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\toriginIp,\n\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\toriginHost,\n\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tadUser,\n\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tadDisplayName,\n\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tdetectedVersion );\n\n}\n\n\n\nbool CimedVersionAlertPresenter::handleFeatureMessage( VeyonWorkerInterface& worker, const FeatureMessage& message )\n\n{\n\n\tQ_UNUSED( worker )\n\n\tQ_UNUSED( message )\n\n\treturn false;\n\n}\n\n\n",
        "implementation": [
          "BuiltinFeatures registra presenter.",
          "IPC para sessão interativa do usuário.",
          "Não abre diálogo no processo do serviço."
        ]
