        "code": "import { ClassEvent } from \"../util/ClassEvent\";\n\nexport class Model extends ClassEvent {\n\n    constructor() {\n\n        super();\n        this._data = {};\n\n    }\n\n    fromJSON(json) {\n\n        this._data = Object.assign(this._data, json);\n        this.trigger('datachange', this.toJSON());\n\n    }\n\n    toJSON() {\n\n        return this._data;\n\n    }\n\n}",
