        "file": "accounts/templates/accounts/register.html",
        "code": "{% extends \"main.html\" %}\n\n{% load widget_tweaks %}\n\n{% block title %}Registro | {{ block.super }}{% endblock %}\n\n{% block content %}\n<div class=\"row col-md-7 offset-md-3\" style=\"padding: 70px;\">\n    <div>\n        <div class=\"page-header\">\n            <h1>Cadastre-se</h1>\n        </div>\n        <form class=\"form-horizontal\" method=\"post\">\n            {% csrf_token %}\n            {% for error in form.non_field_errors %}\n            <div class=\"alert alert-danger\">\n                {{ error }}\n            </div>\n            {% endfor %}\n            <fieldset>\n                {% for field in form %}\n                <div class=\"form-group{% if field.errors %} has-error{% endif %}\">\n                  <label for=\"{{ field.auto_id }}\" class=\"col-md-3 control-label\">{{ field.label }}</label>\n                  <div class=\"col-md-9\">\n                    {% render_field field class=\"form-control\" %}\n                    {% for error in field.errors %}\n                    <span class=\"help-block\">{{ error }}</span>\n                    {% endfor %}\n                  </div>\n                </div>\n                {% endfor %}\n                <div class=\"form-group\">\n                  <div class=\"col-md-9 col-md-offset-3\">\n                    <button type=\"submit\" class=\"btn btn-primary\">Registrar</button>\n                  </div>\n                </div>\n            </fieldset>\n        </form>\n    </div>\n</div>\n{% endblock %}\n",
