        "file": "views/search.ejs",
        "code": "<!DOCTYPE html>\n<html lang=\"pt-br\">\n\n\t<%- include(\"inc/head-search\") -%>\n\n<body>\n\t<%- include(\"inc/header-menu\") -%>\n\t\n\t\t<main id=\"principal\">\n\t\t\t\n\t\t\t<form name=\"meu_form\" class=\"data-ax-form\" action=\"/search\" method=\"post\" >\n\n\t\t\t\t<div id=\"alerts\" style=\"padding: 10px 0px; text-transform: uppercase; color: green;\">\n\t\t\t\t\t<%- include('inc/alerts') -%>\n\t\t\t\t</div> \n\n\t\t\t\t<div>\n\t\t\t\t\t<h1 class=\"\">PESQUISA SOBRE A CIDADE</h1>\n\t\t\t\t</div>\t\t\t\t\n\n\t\t\t\t<fieldset class=\"grupo\">\t\t\t\t\t\t\t\t\n\t\t\t\t\t<div class=\"campo\">\n\t\t\t\t\t\t<label for=\"cep\">Cep</label>\n\t\t\t\t\t\t<input type=\"tel\" placeholder=\"Informe o Cep\" id=\"cep\" name=\"cep\" autofocus value=\"<%= body.cep %>\">\n\t\t\t\t\t</div>\n\t\t\t\t\t<div class=\"campo\">\n\t\t\t\t\t\t<label for=\"cidade\">Cidade</label>\n\t\t\t\t\t\t<input type=\"text\" placeholder=\"Informe a cidade\" id=\"cidade\" name=\"cidade\" value=\"<%= body.cidade %>\">\n\t\t\t\t\t</div>\n\t\t\t\t</fieldset>\n\t\t\t\t<fieldset class=\"grupo\">\n\t\t\t\t\t<div class=\"campo\">\n\t\t\t\t\t\t<label for=\"uf\">UF</label>\n\t\t\t\t\t\t<input type=\"text\" placeholder=\"UF\" name=\"uf\" id=\"uf\" value=\"<%= body.uf %>\">\n\t\t\t\t\t</div>\n\t\t\t\t\t<div class=\"campo\">\n\t\t\t\t\t\t<label for=\"bairro\">Bairro</label>\n\t\t\t\t\t\t<input type=\"text\" placeholder=\"Informe o Bairro\" name=\"bairro\" id=\"bairro\" value=\"<%= body.bairro %>\">\n\t\t\t\t\t</div>\n\t\t\t\t</fieldset>\n\t\t\t\t<fieldset>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<h3>Informe seu sexo:</h3>\n\t\t\t\t\t\t<input type=\"radio\" id=\"masculino\" name=\"sexo\" value=\"M\">\n\t\t\t\t\t\t<label for=\"masculino\">Masculino</label>\n\t\t\t\t\t\t<input type=\"radio\" id=\"feminino\" name=\"sexo\" value=\"F\">\n\t\t\t\t\t\t<label for=\"feminino\">Feminino</label>\n\t\t\t\t\t\t<input type=\"radio\" id=\"prefiro_nao_dizer\" name=\"sexo\" value=\"N\">\n\t\t\t\t\t\t<label for=\"prefiro_nao_dizer\">Prefiro não dizer</label>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div class=\"campo\">\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<h3>Informe sua faixa etária:</h3>\n\t\t\t\t\t\t\t<label for=\"classe_a\"><input type=\"radio\" id=\"classe_a\" name=\"classesocial\" value=\"classe A\">Acima de 60 anos</label>\n\t\t\t\t\t\t\t<label for=\"classe_b\"><input type=\"radio\" id=\"classe_b\" name=\"classesocial\" value=\"classe B\">De 30 a 59 anos</label>\n\t\t\t\t\t\t\t<label for=\"classe_c\"><input type=\"radio\" id=\"classe_c\" name=\"classesocial\" value=\"classe C\">De 19 a 29 anos</label>\n\t\t\t\t\t\t\t<label for=\"classe_e\"><input type=\"radio\" id=\"classe_e\" name=\"classesocial\" value=\"classe E\">Até 18 anos</label>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</fieldset>\n\t\t\t\t<fieldset>\n\t\t\t\t\t<div class=\"campo\">\n\t\t\t\t\t\t<h3>Qual setor precisa mais de investimento?</h3>\n\t\t\t\t\t\t<label for=\"saude\"><input type=\"radio\" id=\"saude\" name=\"pesquisageral\" value=\"saude\">Saúde</label>\n\t\t\t\t\t\t<label for=\"cultura\"><input type=\"radio\" id=\"cultura\" name=\"pesquisageral\" value=\"cultura\">Cultura</label>\n\t\t\t\t\t\t<label for=\"educacao\"><input type=\"radio\" id=\"educacao\" name=\"pesquisageral\" value=\"educacao\">Educação</label>\n\t\t\t\t\t\t<label for=\"lazer\"><input type=\"radio\" id=\"lazer\" name=\"pesquisageral\" value=\"lazer\">Lazer</label>\n\t\t\t\t\t\t<label for=\"turismo\"><input type=\"radio\" id=\"turismo\" name=\"pesquisageral\" value=\"turismo\">Turismo</label>\n\t\t\t\t\t\t<label for=\"esporte\"><input type=\"radio\" id=\"esporte\" name=\"pesquisageral\" value=\"esporte\">Esporte</label>\n\t\t\t\t\t\t<label for=\"meio_ambiente\"><input type=\"radio\" id=\"meio_ambiente\" name=\"pesquisageral\" value=\"meio_ambiente\">Meio ambiente</label>\n\t\t\t\t\t\t<label for=\"assistencia_social\"><input type=\"radio\" id=\"assistencia_social\" name=\"pesquisageral\" value=\"assistencia_social\">Assistência social</label>\n\t\t\t\t\t</div>\n\t\t\t\t</fieldset>\n\t\t\t\t<input type=\"submit\" class=\"botao\" onclick=\"Enviar();\" value=\"Enviar\" />\n\t\t\t</form>\n\t\t</div>\n\t\t\n\t</main>\n\t<%- include(\"inc/cep-scripts\") -%>\n\t<%- include(\"inc/footer\") -%>\n\t<%- include(\"inc/footer-scripts\") -%>\t\n\t\n</body>\n\n</html>",
