        "file": "pedido/views.py",
        "code": "from django.shortcuts import redirect, reverse\nfrom django.views.generic import ListView, DetailView\nfrom django.views import View\n# from django.http import HttpResponse\nfrom django.contrib import messages\n\nfrom produto.models import Variacao\nfrom .models import Pedido, ItemPedido\n\nfrom utils import utils\n\n\nclass DispatchLoginRequiredMixin(View):\n    def dispatch(self, *args, **kwargs):\n        if not self.request.user.is_authenticated:\n            return redirect('perfil:criar')\n\n        return super().dispatch(*args, **kwargs)\n\n    def get_queryset(self, *args, **kwargs):\n        qs = super().get_queryset(*args, **kwargs)\n        qs = qs.filter(usuario=self.request.user)\n        return qs\n\n\nclass Pagar(DispatchLoginRequiredMixin, DetailView):\n    template_name = 'pedido/pagar.html'\n    model = Pedido\n    pk_url_kwarg = 'pk'\n    context_object_name = 'pedido'\n\n\nclass SalvarPedido(View):\n    template_name = 'pedido/pagar.html'\n\n    def get(self, *args, **kwargs):\n        if not self.request.user.is_authenticated:\n            messages.error(\n                self.request,\n                'Você precisa fazer login.'\n            )\n            return redirect('perfil:criar')\n\n        if not self.request.session.get('carrinho'):\n            messages.error(\n                self.request,\n                'Seu carrinho está vazio.'\n            )\n            return redirect('produto:lista')\n\n        carrinho = self.request.session.get('carrinho')\n        carrinho_variacao_ids = [v for v in carrinho]\n        bd_variacoes = list(\n            Variacao.objects.select_related('produto')\n            .filter(id__in=carrinho_variacao_ids)\n        )\n\n        for variacao in bd_variacoes:\n            vid = str(variacao.id)\n\n            estoque = variacao.estoque\n            qtd_carrinho = carrinho[vid]['quantidade']\n            preco_unt = carrinho[vid]['preco_unitario']\n            preco_unt_promo = carrinho[vid]['preco_unitario_promocional']\n\n            error_msg_estoque = ''\n\n            if estoque < qtd_carrinho:\n                carrinho[vid]['quantidade'] = estoque\n                carrinho[vid]['preco_quantitativo'] = estoque * preco_unt\n                carrinho[vid]['preco_quantitativo_promocional'] = estoque * \\\n                    preco_unt_promo\n\n                error_msg_estoque = 'Estoque insuficiente para alguns '\\\n                    'produtos do seu carrinho. '\\\n                    'Reduzimos a quantidade desses produtos. Por favor, '\\\n                    'verifique quais produtos foram afetados a seguir.'\n\n            if error_msg_estoque:\n                messages.error(\n                    self.request,\n                    error_msg_estoque\n                )\n\n                self.request.session.save()\n                return redirect('produto:carrinho')\n\n        qtd_total_carrinho = utils.cart_total_qtd(carrinho)\n        valor_total_carrinho = utils.cart_totals(carrinho)\n\n        pedido = Pedido(\n            usuario=self.request.user,\n            total=valor_total_carrinho,\n            qtd_total=qtd_total_carrinho,\n            status='C',\n        )\n\n        pedido.save()\n\n        ItemPedido.objects.bulk_create(\n            [\n                ItemPedido(\n                    pedido=pedido,\n                    produto=v['produto_nome'],\n                    produto_id=v['produto_id'],\n                    variacao=v['variacao_nome'],\n                    variacao_id=v['variacao_id'],\n                    preco=v['preco_quantitativo'],\n                    preco_promocional=v['preco_quantitativo_promocional'],\n                    quantidade=v['quantidade'],\n                    imagem=v['imagem'],\n                ) for v in carrinho.values()\n            ]\n        )\n\n        del self.request.session['carrinho']\n\n        return redirect(\n            reverse(\n                'pedido:pagar',\n                kwargs={\n                    'pk': pedido.pk\n                }\n            )\n        )\n\n\nclass Detalhe(DispatchLoginRequiredMixin, DetailView):\n    model = Pedido\n    context_object_name = 'pedido'\n    template_name = 'pedido/detalhe.html'\n    pk_url_kwarg = 'pk'\n\n\nclass Lista(DispatchLoginRequiredMixin, ListView):\n    model = Pedido\n    context_object_name = 'pedidos'\n    template_name = 'pedido/lista.html'\n    paginate_by = 10\n    ordering = ['-id']\n",
