        "file": "labs/05_spyware_telemetry/simulate_spyware.py",
        "code": "#!/usr/bin/env python3\n\"\"\"\nLab 05 — Spyware / telemetria abusiva (SIMULAÇÃO).\n\nGera eventos de coleta de dados sensíveis fictícios para treinar detecção.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom common import TelemetryBus, print_banner\n\n\ndef simulate_spyware(bus: TelemetryBus) -> None:\n    samples = [\n        (\"keylog\", \"input.buffer\", \"buffer fictício: ****\"),\n        (\"clipboard\", \"clip.store\", \"conteúdo mascarado\"),\n        (\"screenshot\", \"display.frame\", \"frame não capturado — só evento\"),\n        (\"location\", \"geo.fake\", \"-23.55,-46.63 (exemplo)\"),\n        (\"exfil\", \"https://telemetry.invalid/collect\", \"HTTPS ilustrativo\"),\n    ]\n    for action, target, detail in samples:\n        bus.emit(\"spyware\", action, target, detail, \"high\")\n\n\ndef main() -> None:\n    print_banner(\"05 · Spyware — telemetria abusiva\")\n    bus = TelemetryBus()\n    simulate_spyware(bus)\n    out = ROOT / \"demos\" / \"telemetry_spyware.json\"\n    bus.dump_json(str(out))\n    print(f\"\\nTelemetria salva em: {out}\")\n\n\nif __name__ == \"__main__\":\n    main()",
