        "id": "dz-labs-08-behavioral-analyzer-analyzer-py",
        "parent": "dz-labs-def",
        "layer": "file",
        "title": "analyzer.py",
        "description": "Arquivo educacional `labs/08_behavioral_analyzer/analyzer.py` — risco/conceito/prevenção.",
        "file": "labs/08_behavioral_analyzer/analyzer.py",
        "code": "#!/usr/bin/env python3\n\"\"\"\nLab 08 — Analisador comportamental (score por categorias).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport sys\nfrom collections import Counter\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom common.banner import print_banner\n\nWEIGHTS = {\n    \"infect\": 5,\n    \"encrypt\": 8,\n    \"exfil\": 9,\n    \"keylog\": 9,\n    \"persist\": 6,\n    \"probe\": 3,\n    \"collect\": 4,\n    \"hide\": 8,\n    \"c2\": 9,\n    \"checkin\": 4,\n    \"fake_alert\": 5,\n    \"cpu_spike\": 6,\n    \"lolbin\": 7,\n    \"autoopen\": 6,\n    \"fire\": 9,\n    \"listen\": 8,\n    \"link\": 6,\n    \"typosquat\": 8,\n    \"trojanized_update\": 9,\n    \"credential_harvest\": 8,\n}\n\n\ndef score_file(path: Path) -> tuple[int, Counter]:\n    events = json.loads(path.read_text(encoding=\"utf-8\"))\n    actions = Counter(e.get(\"action\", \"\") for e in events)\n    total = sum(WEIGHTS.get(a, 1) * c for a, c in actions.items())\n    return total, actions\n\n\ndef verdict(score: int) -> str:\n    if score >= 20:\n        return \"MALICIOUS (simulado)\"\n    if score >= 8:\n        return \"SUSPICIOUS\"\n    return \"BENIGN / baixo sinal\"\n\n\ndef main() -> None:\n    print_banner(\"08 · Analisador comportamental\")\n    demo = ROOT / \"demos\"\n    files = sorted(demo.glob(\"telemetry_*.json\"))\n    if not files:\n        print(\"Rode demos/run_all_sims.py primeiro.\")\n        return\n    rows = []\n    for f in files:\n        total, actions = score_file(f)\n        v = verdict(total)\n        print(f\"{f.name:32} score={total:3}  → {v}\")\n        print(f\"    ações: {dict(actions)}\")\n        rows.append({\"file\": f.name, \"score\": total, \"verdict\": v, \"actions\": dict(actions)})\n    out = demo / \"behavior_scores.json\"\n    out.write_text(json.dumps(rows, indent=2, ensure_ascii=False), encoding=\"utf-8\")\n    print(f\"\\nScores: {out}\")\n\n\nif __name__ == \"__main__\":\n    main()",
