        "code": "services:\n  postgres:\n    image: postgres:16-alpine\n    environment:\n      POSTGRES_USER: ${POSTGRES_USER:-sentinel}\n      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-sentinel_secret}\n      POSTGRES_DB: ${POSTGRES_DB:-sentinelai}\n    volumes:\n      - postgres_data:/var/lib/postgresql/data\n    ports:\n      - \"5432:5432\"\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U ${POSTGRES_USER:-sentinel} -d ${POSTGRES_DB:-sentinelai}\"]\n      interval: 5s\n      timeout: 5s\n      retries: 5\n\n  redis:\n    image: redis:7-alpine\n    ports:\n      - \"6379:6379\"\n    healthcheck:\n      test: [\"CMD\", \"redis-cli\", \"ping\"]\n      interval: 5s\n      timeout: 3s\n      retries: 5\n\n  api:\n    build:\n      context: ./backend\n      dockerfile: Dockerfile\n    command: uvicorn app.main:app --host 0.0.0.0 --port 8000 --reload --timeout-graceful-shutdown 3\n    env_file:\n      - .env\n    environment:\n      DATABASE_URL: postgresql+asyncpg://sentinel:sentinel_secret@postgres:5432/sentinelai\n      DATABASE_URL_SYNC: postgresql://sentinel:sentinel_secret@postgres:5432/sentinelai\n      REDIS_URL: redis://redis:6379/0\n    volumes:\n      - ./backend:/app\n      - reports_data:/app/reports\n    ports:\n      - \"8000:8000\"\n      - \"2055:2055/udp\"\n    depends_on:\n      postgres:\n        condition: service_healthy\n      redis:\n        condition: service_healthy\n    healthcheck:\n      test: [\"CMD-SHELL\", \"python -c \\\"import urllib.request; urllib.request.urlopen('http://127.0.0.1:8000/health')\\\"\"]\n      interval: 10s\n      timeout: 5s\n      retries: 5\n      start_period: 15s\n    cap_add:\n      - NET_RAW\n\n  worker:\n    build:\n      context: ./backend\n      dockerfile: Dockerfile\n    command: celery -A app.workers.celery_app worker --loglevel=info --concurrency=4 -Q celery\n    env_file:\n      - .env\n    environment:\n      DATABASE_URL: postgresql+asyncpg://sentinel:sentinel_secret@postgres:5432/sentinelai\n      DATABASE_URL_SYNC: postgresql://sentinel:sentinel_secret@postgres:5432/sentinelai\n      REDIS_URL: redis://redis:6379/0\n    volumes:\n      - ./backend:/app\n      - reports_data:/app/reports\n    depends_on:\n      postgres:\n        condition: service_healthy\n      redis:\n        condition: service_healthy\n    cap_add:\n      - NET_RAW\n\n  discovery-worker:\n    build:\n      context: ./backend\n      dockerfile: Dockerfile\n    command: celery -A app.workers.celery_app worker --loglevel=info --concurrency=2 -Q discovery\n    env_file:\n      - .env\n    environment:\n      DATABASE_URL: postgresql+asyncpg://sentinel:sentinel_secret@postgres:5432/sentinelai\n      DATABASE_URL_SYNC: postgresql://sentinel:sentinel_secret@postgres:5432/sentinelai\n      REDIS_URL: redis://redis:6379/0\n    volumes:\n      - ./backend:/app\n      - reports_data:/app/reports\n    depends_on:\n      postgres:\n        condition: service_healthy\n      redis:\n        condition: service_healthy\n    cap_add:\n      - NET_RAW\n\n  beat:\n    build:\n      context: ./backend\n      dockerfile: Dockerfile\n    command: celery -A app.workers.celery_app beat --loglevel=info\n    env_file:\n      - .env\n    environment:\n      DATABASE_URL: postgresql+asyncpg://sentinel:sentinel_secret@postgres:5432/sentinelai\n      DATABASE_URL_SYNC: postgresql://sentinel:sentinel_secret@postgres:5432/sentinelai\n      REDIS_URL: redis://redis:6379/0\n    volumes:\n      - ./backend:/app\n    depends_on:\n      - worker\n      - redis\n\n  frontend:\n    build:\n      context: ./frontend\n      dockerfile: Dockerfile\n    command: sh -c \"rm -rf node_modules/.vite && npm install && npm run dev\"\n    ports:\n      - \"5173:5173\"\n    volumes:\n      - ./frontend:/app\n      - /app/node_modules\n    environment:\n      # Vazio = browser usa /api via proxy Vite (mesma origem, sem CORS, reconecta após restart da API)\n      VITE_API_URL: \"\"\n    depends_on:\n      api:\n        condition: service_healthy\n\nvolumes:\n  postgres_data:\n  reports_data:",
