        "id": "sai-discovery-api",
        "parent": "sai-root",
        "layer": "module",
        "title": "API Discovery",
        "description": "Jobs assíncronos de scan, perfis nmap, stop e listagem.",
        "file": "backend/app/api/routes/discovery.py",
        "code": "import time\n\nfrom fastapi import APIRouter, Depends, HTTPException, status\nfrom sqlalchemy import select\nfrom sqlalchemy.ext.asyncio import AsyncSession\n\nfrom app.config import settings\nfrom app.database import get_db\nfrom app.dependencies import require_operator, require_viewer\nfrom app.engines.discovery.dns_resolver import iter_host_addresses, validate_subnet\nfrom app.models import DiscoveryJob, DiscoveryJobStatus, User\nfrom app.engines.discovery.scan_options import list_scan_defaults, resolve_scan_options\nfrom app.schemas.discovery import (\n    DiscoveryJobCreate,\n    DiscoveryJobResponse,\n    ScanDefaultsResponse,\n)\nfrom app.services.discovery_service import (\n    cycle_discovery_job_ids_if_needed,\n    fail_stuck_pending_discovery_jobs,\n    fail_orphaned_discovery_jobs,\n    fail_stale_discovery_jobs,\n    has_active_discovery_job,\n    prune_discovery_jobs,\n    reconcile_cancelled_discovery_jobs,\n    stop_discovery_job,\n)\nfrom app.workers.discovery_tasks import run_discovery_job\n\nrouter = APIRouter()\n\nMAX_JOBS = settings.discovery_jobs_max_history\n_RECONCILE_INTERVAL_SECONDS = 30.0\n_last_reconcile_monotonic = 0.0\n\n\ndef _maybe_reconcile_discovery_jobs() -> None:\n    \"\"\"Reconcilia jobs órfãos/stale no máximo a cada 30s (evita esgotar pool no polling).\"\"\"\n    global _last_reconcile_monotonic\n    now = time.monotonic()\n    if now - _last_reconcile_monotonic < _RECONCILE_INTERVAL_SECONDS:\n        return\n    _last_reconcile_monotonic = now\n\n    from app.db_sync import SyncSession\n\n    with SyncSession() as session:\n        stale = fail_stale_discovery_jobs(session)\n        stuck = fail_stuck_pending_discovery_jobs(session)\n        orphaned = fail_orphaned_discovery_jobs(session)\n        reconciled = reconcile_cancelled_discovery_jobs(session)\n        if stale or stuck or orphaned or reconciled:\n            session.commit()\n\n\n@router.get(\"\", response_model=list[DiscoveryJobResponse])\nasync def list_discovery_jobs(\n    limit: int = MAX_JOBS,\n    db: AsyncSession = Depends(get_db),\n    _: User = Depends(require_viewer),\n):\n    cap = min(max(limit, 1), MAX_JOBS)\n\n    _maybe_reconcile_discovery_jobs()\n\n    result = await db.execute(\n        select(DiscoveryJob).order_by(DiscoveryJob.created_at.desc()).limit(cap)\n    )\n    return result.scalars().all()\n\n\n@router.get(\"/scan-defaults\", response_model=ScanDefaultsResponse)\nasync def get_scan_defaults(_: User = Depends(require_viewer)):\n    return list_scan_defaults()\n\n\ndef _build_scan_options_payload(payload: DiscoveryJobCreate) -> dict:\n    if payload.scan_options:\n        opts = payload.scan_options.model_dump(exclude_none=True)\n    else:\n        opts = {\"profile\": \"standard\"}\n\n    if payload.scan_options is None or payload.scan_options.use_snmp is None:\n        opts[\"use_snmp\"] = payload.use_snmp\n    community = payload.snmp_community or opts.get(\"snmp_community\")\n    if community:\n        opts[\"snmp_community\"] = community\n    return opts\n\n\n@router.post(\"\", response_model=DiscoveryJobResponse, status_code=status.HTTP_202_ACCEPTED)\nasync def start_discovery(\n    payload: DiscoveryJobCreate,\n    db: AsyncSession = Depends(get_db),\n    _: User = Depends(require_operator),\n):\n    try:\n        validate_subnet(payload.subnet)\n    except ValueError as exc:\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(exc)) from exc\n\n    from app.db_sync import SyncSession\n\n    with SyncSession() as session:\n        if has_active_discovery_job(session):\n            raise HTTPException(\n                status_code=status.HTTP_409_CONFLICT,\n                detail=\"Já existe um scan em andamento. Cancele-o antes de iniciar outro.\",\n            )\n        cycle_discovery_job_ids_if_needed(session)\n        session.commit()\n\n    scan_opts_dict = _build_scan_options_payload(payload)\n    resolved = resolve_scan_options(\n        scan_opts_dict,\n        snmp_community_fallback=payload.snmp_community or settings.snmp_community,\n    )\n\n    job = DiscoveryJob(\n        subnet=payload.subnet,\n        use_snmp=resolved.use_snmp,\n        snmp_community=resolved.snmp_community,\n        scan_options=scan_opts_dict,\n        status=DiscoveryJobStatus.PENDING,\n        progress_percent=0,\n        progress_label=f\"Aguardando worker · perfil {resolved.label}\",\n        hosts_processed=0,\n        devices_found=0,\n        devices_inactive=0,\n        total_hosts=len(iter_host_addresses(payload.subnet)),\n    )\n    db.add(job)\n    await db.flush()\n\n    async_result = run_discovery_job.apply_async(args=[job.id], queue=\"discovery\", priority=9)\n    job.celery_task_id = async_result.id\n    await db.commit()\n    await db.refresh(job)\n\n    with SyncSession() as session:\n        prune_discovery_jobs(session, keep=MAX_JOBS)\n        session.commit()\n\n    return job\n\n\n@router.post(\"/{job_id}/stop\", response_model=DiscoveryJobResponse)\nasync def stop_discovery(\n    job_id: int,\n    db: AsyncSession = Depends(get_db),\n    _: User = Depends(require_operator),\n):\n    job = await db.get(DiscoveryJob, job_id)\n    if not job:\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\"Job não encontrado\")\n\n    if job.status in (DiscoveryJobStatus.COMPLETED, DiscoveryJobStatus.FAILED):\n        return job\n\n    from app.db_sync import SyncSession\n\n    with SyncSession() as session:\n        sync_job = session.get(DiscoveryJob, job_id)\n        if not sync_job:\n            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\"Job não encontrado\")\n        stop_discovery_job(session, sync_job)\n        session.commit()\n        session.refresh(sync_job)\n        response = DiscoveryJobResponse.model_validate(sync_job)\n\n    return response\n\n\n@router.get(\"/{job_id}\", response_model=DiscoveryJobResponse)\nasync def get_discovery_job(\n    job_id: int,\n    db: AsyncSession = Depends(get_db),\n    _: User = Depends(require_viewer),\n):\n    job = await db.get(DiscoveryJob, job_id)\n    if not job:\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\"Job não encontrado\")\n    return job",
